/// Material editor toolbar — name, domain, shading model, blend mode, save/load.

import type { UzMatFile, MaterialDomain, ShadingModel, BlendMode } from '../model/types';

interface Props {
  material: UzMatFile;
  onMaterialChange: (mat: UzMatFile) => void;
  onLoad: () => void;
  onSave: () => void;
  onNew: () => void;
  canUndo: boolean;
  canRedo: boolean;
  onUndo: () => void;
  onRedo: () => void;
}

const DOMAINS: MaterialDomain[] = ['Surface', 'PostProcess', 'Decal', 'UI'];
const SHADING_MODELS: ShadingModel[] = ['DefaultLit', 'Unlit', 'Subsurface'];
const BLEND_MODES: BlendMode[] = ['Opaque', 'Masked', 'Translucent'];

export function Toolbar({
  material,
  onMaterialChange,
  onLoad,
  onSave,
  onNew,
  canUndo,
  canRedo,
  onUndo,
  onRedo,
}: Props) {
  function updateField<K extends keyof UzMatFile>(key: K, value: UzMatFile[K]) {
    onMaterialChange({ ...material, [key]: value });
  }

  return (
    <div className="app-toolbar">
      <span className="toolbar-title">Material Editor</span>
      <div className="toolbar-separator" />

      <button onClick={onNew}>New</button>
      <button onClick={onLoad}>Open</button>
      <button onClick={onSave}>Save</button>

      <div className="toolbar-separator" />

      <button onClick={onUndo} disabled={!canUndo} title="Ctrl+Z">Undo</button>
      <button onClick={onRedo} disabled={!canRedo} title="Ctrl+Y">Redo</button>

      <div className="toolbar-separator" />

      <label>Name</label>
      <input
        type="text"
        value={material.name}
        style={{ width: 140 }}
        onChange={(e) => updateField('name', e.target.value)}
      />

      <label>Domain</label>
      <select
        value={material.domain}
        onChange={(e) => updateField('domain', e.target.value as MaterialDomain)}
      >
        {DOMAINS.map((d) => (
          <option key={d} value={d}>{d}</option>
        ))}
      </select>

      <label>Shading</label>
      <select
        value={material.shadingModel}
        onChange={(e) => updateField('shadingModel', e.target.value as ShadingModel)}
      >
        {SHADING_MODELS.map((s) => (
          <option key={s} value={s}>{s}</option>
        ))}
      </select>

      <label>Blend</label>
      <select
        value={material.blendMode ?? 'Opaque'}
        onChange={(e) => updateField('blendMode', e.target.value as BlendMode)}
      >
        {BLEND_MODES.map((b) => (
          <option key={b} value={b}>{b}</option>
        ))}
      </select>

      <label style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
        <input
          type="checkbox"
          checked={material.twoSided ?? false}
          onChange={(e) => updateField('twoSided', e.target.checked)}
        />
        Two Sided
      </label>
    </div>
  );
}

export default Toolbar;
