/// Constant node — inline value editors (number inputs, color picker).
/// Uses data.exprType directly from the MaterialExpression to determine which editor to show.

import { BaseExpressionNode, type ExprNodeProps } from './BaseExpressionNode';
import { MatExprType } from '../model/types';

function ScalarEditor({ value, onChange }: { value: number; onChange: (v: number) => void }) {
  return (
    <input
      type="number"
      className="mat-node-inline-input"
      value={value}
      step={0.01}
      onChange={(e) => onChange(parseFloat(e.target.value) || 0)}
    />
  );
}

function VectorEditor({
  keys,
  params,
  onChange,
}: {
  keys: string[];
  params: Record<string, number>;
  onChange: (key: string, value: number) => void;
}) {
  return (
    <div style={{ display: 'flex', gap: 2 }}>
      {keys.map((k) => (
        <input
          key={k}
          type="number"
          className="mat-node-inline-input"
          value={params[k] ?? 0}
          step={0.01}
          title={k.toUpperCase()}
          onChange={(e) => onChange(k, parseFloat(e.target.value) || 0)}
        />
      ))}
    </div>
  );
}

function ColorEditor({
  params,
  onChange,
}: {
  params: Record<string, number>;
  onChange: (key: string, value: number) => void;
}) {
  const r = Math.round(Math.min(1, Math.max(0, params['r'] ?? 1)) * 255);
  const g = Math.round(Math.min(1, Math.max(0, params['g'] ?? 1)) * 255);
  const b = Math.round(Math.min(1, Math.max(0, params['b'] ?? 1)) * 255);
  const hexColor = `#${r.toString(16).padStart(2, '0')}${g.toString(16).padStart(2, '0')}${b.toString(16).padStart(2, '0')}`;

  return (
    <div style={{ display: 'flex', gap: 4, alignItems: 'center' }}>
      <input
        type="color"
        value={hexColor}
        style={{ width: 28, height: 22, padding: 0, border: 'none', cursor: 'pointer' }}
        onChange={(e) => {
          const hex = e.target.value;
          onChange('r', parseInt(hex.slice(1, 3), 16) / 255);
          onChange('g', parseInt(hex.slice(3, 5), 16) / 255);
          onChange('b', parseInt(hex.slice(5, 7), 16) / 255);
        }}
      />
      <VectorEditor keys={['r', 'g', 'b']} params={params} onChange={onChange} />
    </div>
  );
}

export function ConstantNode(props: ExprNodeProps) {
  const { data } = props;
  const handleScalarChange = (key: string, value: number) => {
    data.onParamChange?.(data.exprId, 'scalar', key, value);
  };

  return (
    <BaseExpressionNode {...props}>
      <div className="mat-node-inline-editor">
        {data.exprType === MatExprType.ScalarConstant && (
          <ScalarEditor
            value={data.scalarParams['value'] ?? 0}
            onChange={(v) => handleScalarChange('value', v)}
          />
        )}
        {data.exprType === MatExprType.Vector2Constant && (
          <VectorEditor keys={['x', 'y']} params={data.scalarParams} onChange={handleScalarChange} />
        )}
        {data.exprType === MatExprType.Vector3Constant && (
          <VectorEditor keys={['x', 'y', 'z']} params={data.scalarParams} onChange={handleScalarChange} />
        )}
        {data.exprType === MatExprType.Vector4Constant && (
          <VectorEditor keys={['x', 'y', 'z', 'w']} params={data.scalarParams} onChange={handleScalarChange} />
        )}
        {data.exprType === MatExprType.ColorConstant && (
          <ColorEditor params={data.scalarParams} onChange={handleScalarChange} />
        )}
      </div>
    </BaseExpressionNode>
  );
}

export default ConstantNode;
