/// Base expression node shell — shared header + handle list + body slot.
/// All custom material nodes wrap this component.

import { Handle, Position, type NodeProps } from '@xyflow/react';
import { type MatPin, MatPinDir, MatExprType, pinTypeColor, type ExprCategory } from '../model/types';

const CATEGORY_COLORS: Record<ExprCategory, string> = {
  Output: 'var(--header-output)',
  Constants: 'var(--header-constants)',
  Math: 'var(--header-math)',
  Texture: 'var(--header-texture)',
  Coordinates: 'var(--header-coordinates)',
  Procedural: 'var(--header-procedural)',
  Utility: 'var(--header-utility)',
  Parameters: 'var(--header-parameters)',
};

export interface ExprNodeData extends Record<string, unknown> {
  label: string;
  category: ExprCategory;
  exprId: number;
  exprType: MatExprType;
  inputs: MatPin[];
  outputs: MatPin[];
  scalarParams: Record<string, number>;
  stringParams: Record<string, string>;
  intParams: Record<string, number>;
  onParamChange?: (exprId: number, paramType: 'scalar' | 'string' | 'int', key: string, value: number | string) => void;
}

export type ExprNodeProps = NodeProps & { data: ExprNodeData };

export function BaseExpressionNode({
  data,
  selected,
  children,
}: ExprNodeProps & { children?: React.ReactNode }) {
  const headerColor = CATEGORY_COLORS[data.category] ?? 'var(--header-utility)';
  const inputPins = data.inputs;
  const outputPins = data.outputs;
  const maxPins = Math.max(inputPins.length, outputPins.length);

  return (
    <div className={`mat-node ${selected ? 'selected' : ''} ${data.category === 'Output' ? 'pbr-output' : ''}`}>
      <div className="mat-node-header" style={{ background: headerColor }}>
        {data.label}
      </div>
      <div className="mat-node-body">
        {Array.from({ length: maxPins }, (_, i) => {
          const inp = inputPins[i];
          const out = outputPins[i];
          return (
            <div key={i} style={{ display: 'flex', justifyContent: 'space-between', minHeight: 18 }}>
              {inp ? (
                <PinRow pin={inp} side="input" />
              ) : (
                <div style={{ flex: 1 }} />
              )}
              {out ? (
                <PinRow pin={out} side="output" />
              ) : (
                <div style={{ flex: 1 }} />
              )}
            </div>
          );
        })}
        {children}
      </div>
    </div>
  );
}

function PinRow({ pin, side }: { pin: MatPin; side: 'input' | 'output' }) {
  const color = pinTypeColor(pin.type);
  const handleId = `${pin.direction === MatPinDir.Input ? 'in' : 'out'}-${pin.id}`;

  return (
    <div className={`mat-node-pin-row ${side}`} style={{ flex: 1 }}>
      <Handle
        type={side === 'input' ? 'target' : 'source'}
        position={side === 'input' ? Position.Left : Position.Right}
        id={handleId}
        style={{
          background: color,
          width: 10,
          height: 10,
          border: '2px solid #1e1e2e',
        }}
      />
      <span className="mat-node-pin-name">{pin.name}</span>
    </div>
  );
}

export default BaseExpressionNode;
