/// Three.js material preview — renders a sphere with PBR material properties
/// derived from the current material graph's constant/param values.

import { useRef, useMemo } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { OrbitControls, Environment } from '@react-three/drei';
import * as THREE from 'three';
import type { UzMatFile } from '../model/types';
import { MatExprType } from '../model/types';

interface Props {
  material: UzMatFile;
}

/// Extract PBR values from the material graph by reading what is connected
/// to the PBROutput node. For constant nodes, we read their scalar params
/// directly. For unconnected pins, we use the pin's default value.
function extractPBRValues(material: UzMatFile) {
  const pbrOutput = material.expressions.find(
    (e) => e.type === MatExprType.PBROutput,
  );
  if (!pbrOutput) {
    return {
      baseColor: new THREE.Color(0.8, 0.8, 0.8),
      metallic: 0.0,
      roughness: 0.5,
      emissive: new THREE.Color(0, 0, 0),
      opacity: 1.0,
    };
  }

  function resolveFloat(pinId: number, fallback: number): number {
    const pin = pbrOutput!.inputs.find((p) => p.id === pinId);
    if (!pin || pin.connectedExprId === 0) return fallback;
    const srcExpr = material.expressions.find((e) => e.id === pin.connectedExprId);
    if (!srcExpr) return fallback;
    if (srcExpr.type === MatExprType.ScalarConstant) {
      return srcExpr.scalarParams['value'] ?? fallback;
    }
    return fallback;
  }

  function resolveColor(pinId: number, fallbackR: number, fallbackG: number, fallbackB: number): THREE.Color {
    const pin = pbrOutput!.inputs.find((p) => p.id === pinId);
    if (!pin || pin.connectedExprId === 0) return new THREE.Color(fallbackR, fallbackG, fallbackB);
    const srcExpr = material.expressions.find((e) => e.id === pin.connectedExprId);
    if (!srcExpr) return new THREE.Color(fallbackR, fallbackG, fallbackB);

    if (srcExpr.type === MatExprType.Vector3Constant) {
      return new THREE.Color(
        srcExpr.scalarParams['x'] ?? fallbackR,
        srcExpr.scalarParams['y'] ?? fallbackG,
        srcExpr.scalarParams['z'] ?? fallbackB,
      );
    }
    if (srcExpr.type === MatExprType.ColorConstant) {
      return new THREE.Color(
        srcExpr.scalarParams['r'] ?? fallbackR,
        srcExpr.scalarParams['g'] ?? fallbackG,
        srcExpr.scalarParams['b'] ?? fallbackB,
      );
    }
    return new THREE.Color(fallbackR, fallbackG, fallbackB);
  }

  // Apply material params multipliers if present
  const params = material.params;
  let baseColor = resolveColor(0, 1, 1, 1);
  if (params?.baseColorTint) {
    baseColor = new THREE.Color(
      baseColor.r * params.baseColorTint[0],
      baseColor.g * params.baseColorTint[1],
      baseColor.b * params.baseColorTint[2],
    );
  }

  let metallic = resolveFloat(1, 0.0);
  if (params?.metallicMultiplier != null) metallic *= params.metallicMultiplier;

  let roughness = resolveFloat(2, 0.5);
  if (params?.roughnessMultiplier != null) roughness *= params.roughnessMultiplier;

  const emissive = resolveColor(4, 0, 0, 0);
  if (params?.emissiveMultiplier != null) {
    emissive.multiplyScalar(params.emissiveMultiplier);
  }

  const opacity = resolveFloat(5, 1.0);

  return { baseColor, metallic, roughness, emissive, opacity };
}

function PreviewSphere({ material }: { material: UzMatFile }) {
  const meshRef = useRef<THREE.Mesh>(null);
  const pbr = useMemo(() => extractPBRValues(material), [material]);

  useFrame((_state, delta) => {
    if (meshRef.current) {
      meshRef.current.rotation.y += delta * 0.3;
    }
  });

  return (
    <mesh ref={meshRef}>
      <sphereGeometry args={[1.2, 64, 64]} />
      <meshStandardMaterial
        color={pbr.baseColor}
        metalness={pbr.metallic}
        roughness={pbr.roughness}
        emissive={pbr.emissive}
        opacity={pbr.opacity}
        transparent={pbr.opacity < 1.0}
      />
    </mesh>
  );
}

export function MaterialPreview({ material }: Props) {
  return (
    <div className="preview-panel">
      <Canvas
        camera={{ position: [0, 0, 3.5], fov: 45 }}
        gl={{ antialias: true, toneMapping: THREE.ACESFilmicToneMapping }}
      >
        <ambientLight intensity={0.3} />
        <directionalLight position={[5, 5, 5]} intensity={1.5} />
        <directionalLight position={[-3, -2, -4]} intensity={0.4} />
        <PreviewSphere material={material} />
        <OrbitControls
          enableDamping
          dampingFactor={0.1}
          minDistance={2}
          maxDistance={8}
        />
        <Environment preset="studio" background={false} />
      </Canvas>
    </div>
  );
}

export default MaterialPreview;
